/* Original illustrated garden assets, rendered as scalable vector scenes. */
function illustratedGarden(s,id='garden'){
 const uid='garden-'+String(id).replace(/[^a-z0-9-]/gi,''),tomato=/помид|томат/i.test(s.crop),carrot=/морков/i.test(s.crop),cucumber=/огур/i.test(s.crop),young=s.stage==='planted';
 const leaf='<path d="M0 0 C-25-25-32-4-11 5Q-4 6 0 0" fill="#58a84b"/><path d="M0-9C17-34 35-18 16-7Q7-2 0-9" fill="#86c84e"/><path d="M0-19C-10-41-23-34-15-21Z" fill="#b0d65b"/>';
 const fruit=tomato?'<g fill="url(#'+uid+'-fruit)"><circle cx="-13" cy="2" r="10"/><circle cx="11" cy="-8" r="9"/><circle cx="8" cy="13" r="10"/></g><g fill="#286444"><path d="M-13-9l2 5 5-1-4 4-3-3-5 2 3-5Z"/><path d="M11-18l2 5 4 1-5 2-4-3Z"/></g><path d="M-17-2l2-2M4 9l2-2" stroke="#ffd7a0" stroke-width="3" stroke-linecap="round"/>':cucumber?'<path d="M-13-5q-13 26 0 29q12-1 8-24M13-16q-8 13-3 22q10 3 12-10" fill="#498b36" stroke="#256b3e" stroke-width="3"/><path d="M-13 2v12M15-9l-2 7" stroke="#a2ce60" stroke-width="2"/><g fill="#ffe16f"><circle cx="-18" cy="-11" r="5"/><circle cx="21" cy="-24" r="5"/></g>':carrot?'<path d="M-12-2Q0-11 10-2L0 31Z" fill="#f48e2e" stroke="#c76825" stroke-width="2"/><path d="M-7 4h9M-4 12h6" stroke="#ffd46b" stroke-width="3"/>':'<path d="M-12-4C-31 21-9 34 0 15L1-3Z" fill="#8550a6" stroke="#583376" stroke-width="2"/><path d="M11-14C-2 5 14 18 22 3L23-13Z" fill="#aa74c2" stroke="#70448f" stroke-width="2"/><path d="M-14 1q-7 9-3 13" stroke="#d3a7df" stroke-width="3" fill="none"/><path d="M-14-7l-6 8 11-3 6 5-2-10M13-17l-5 9 11-4 7 4-3-10" fill="#65a84c"/>';
 const plants=[[83,99],[126,112],[170,125],[105,77],[149,90],[193,103]].map(([x,y],i)=>`<g transform="translate(${x} ${y}) scale(${young?.7:.94})"><ellipse cx="0" cy="20" rx="20" ry="6" fill="#392820" opacity=".25"/><g class="garden-foliage" style="animation-delay:-${i*.7}s"><path d="M0 19Q4-2 0-25" stroke="#397c46" stroke-width="4" fill="none"/>${leaf}${young?'<path d="M0 6Q-14-12-20-1Q-17 12 0 6" fill="#80bb55"/>':fruit}</g></g>`).join('');
 const stone=s.border==='concrete';
 return `<svg class="garden-illustration" viewBox="0 0 280 205" role="img" aria-label="${esc(s.crop)}: ${stone?'объёмный бетонный бортик':'деревянная грядка'}${s.irrigation?', капельный полив':''}"><defs><linearGradient id="${uid}-side" x2="0" y2="1"><stop stop-color="${stone?'#9caeac':'#b88049'}"/><stop offset="1" stop-color="${stone?'#667f7c':'#80532f'}"/></linearGradient><linearGradient id="${uid}-soil" x2="0" y2="1"><stop stop-color="#9c704b"/><stop offset="1" stop-color="#624530"/></linearGradient><radialGradient id="${uid}-fruit" cx=".3" cy=".25"><stop stop-color="#ffab61"/><stop offset=".5" stop-color="#f25a3d"/><stop offset="1" stop-color="#c53532"/></radialGradient></defs><ellipse cx="141" cy="174" rx="115" ry="18" fill="#456a3e" opacity=".18"/><path d="M20 115L110 58 258 105 167 171Z" fill="${stone?'#e4ece5':'#efd3a0'}"/><path d="M20 115L167 162 258 105 258 127 167 187 20 138Z" fill="url(#${uid}-side)"/><path d="M20 115L167 162V187L20 138Z" fill="${stone?'#90a29f':'#b17e4a'}"/><path d="M20 115L110 58 258 105 167 162Z M37 114L167 153 242 106 111 68Z" fill="${stone?'#e0e8de':'#e8bb7d'}" fill-rule="evenodd" stroke="${stone?'#f4f7e9':'#f8d9a1'}" stroke-width="2"/><path d="M37 114L111 68 242 106 167 153Z" fill="url(#${uid}-soil)"/><g stroke="#453623" opacity=".35" stroke-width="4"><path d="M62 109l118 36M83 95l119 37M104 82l119 37"/></g><g stroke="${stone?'#657c78':'#885a36'}" stroke-width="2" opacity=".6"><path d="M57 127v18M94 139v18M131 151v18M199 145v18M229 125v20"/></g>${s.irrigation?'<g stroke="#284f50" stroke-width="4" fill="none"><path d="M53 109l117 36M76 93l117 36M99 79l117 36M53 109l46-30"/></g><g class="garden-droplets" fill="#8de5ef"><path d="M69 99q-8 12 0 12q8 0 0-12M115 113q-8 12 0 12q8 0 0-12M165 98q-8 12 0 12q8 0 0-12"/></g>':''}${plants}<path d="M29 122l129 41" stroke="${stone?'#f7faeb':'#f4d29b'}" stroke-width="3" opacity=".8"/>${s.irrigation?'<g transform="translate(238 72)"><path d="M-5 34V12h-15" fill="none" stroke="#41696b" stroke-width="7"/><rect x="-14" y="8" width="20" height="16" rx="5" fill="#b6e3e0" stroke="#4e8589" stroke-width="2"/><circle cx="-4" cy="16" r="4" fill="#468e9a"/><path d="M-4 16v-3" stroke="white" stroke-width="2"/></g>':''}</svg>`;
}
